<?php
namespace App\Controllers\Api;use App\Support\App;use App\Services\OrderService;
final class BotApiController{public function reply():never{$token=$_SERVER['HTTP_X_BOT_TOKEN']??'';if(!$token||!hash_equals((string)App::setting('bot_api_token',''),$token))App::json(['ok'=>false],401);$in=App::input();$no=(string)($in['order_number']??'');$reply=strtoupper(trim((string)($in['reply']??'')));$q=App::db()->prepare('SELECT id FROM orders WHERE order_number=?');$q->execute([$no]);$id=$q->fetchColumn();if(!$id)App::json(['ok'=>false,'message'=>'Order tidak ditemukan'],404);if(in_array($reply,['D','DONE'],true))(new OrderService())->setStatus((int)$id,'success');elseif(in_array($reply,['F','FAILED'],true))(new OrderService())->setStatus((int)$id,'rejected','WA operator failed');else App::json(['ok'=>false,'message'=>'Reply diabaikan'],422);App::json(['ok'=>true]);}}
